         & = & {{(1 - t)}^{3}A\mathbf{p}_{0} + 3t(1 - t)^{2}A\mathbf{p}_{1} + 3t^{2}(1 - t)A\mathbf{p}_{2} + t^{3}A\mathbf{p}_{3}}
        \end{array}$$

$$\begin{array}{lll}
        {\mathbf{x}(t)} & = & {\left\lbrack \begin{array}{llll}
        \mathbf{p}_{0} & \mathbf{p}_{1} & \mathbf{p}_{2} & \mathbf{p}_{3}
        \end{array} \right\rbrack\left\lbrack \begin{array}{l}
        (1 - t)^{3} \\
        {3t(1 - t)^{2}} \\
        {3t^{2}(1 - t)} \\
        t^{3}
        \end{array} \right\rbrack} \\
         & = & {\left\lbrack \begin{array}{llll}
        \mathbf{p}_{0} & \mathbf{p}_{1} & \mathbf{p}_{2} & \mathbf{p}_{3}
        \end{array} \right\rbrack\left\lbrack \begin{array}{l}
        {1 - 3t + 3t^{2} - t^{3}} \\
        {3t - 6t^{2} + 3t^{3}} \\
        {3t^{2} - 3t^{3}} \\
        t^{3}
        \end{array} \right\rbrack} \\
         & = & {\left\lbrack \begin{array}{llll}
        \mathbf{p}_{0} & \mathbf{p}_{1} & \mathbf{p}_{2} & \mathbf{p}_{3}
        \end{array} \right\rbrack\left\lbrack \begin{array}{rrrr}
        1 & {- 3} & 3 & {- 1} \\
        0 & 3 & {- 6} & 3 \\
        0 & 0 & 3 & {- 3} \\
        0 & 0 & 0 & 1
        \end{array} \right\rbrack\left\lbrack \begin{array}{l}
        1 \\
        t \\
        t^{2} \\
        t^{3}
        \end{array} \right\rbrack}
        \end{array}$$

$$\begin{matrix}
        {\mathbf{x}(s)} & = & {\mathbf{u}{(s)}^{T}M_{B}^{T}\begin{bmatrix}
        \mathbf{p}_{0} \\
        \mathbf{p}_{1} \\
        \mathbf{p}_{2} \\
        \mathbf{p}_{3}
        \end{bmatrix} = \begin{bmatrix}
        1 & s & s^{2} & s^{3}
        \end{bmatrix}\left\lbrack \begin{array}{rrrr}
        1 & 0 & 0 & 0 \\
        {- 3} & 3 & 0 & 0 \\
        3 & {- 6} & 3 & 0 \\
        {- 1} & 3 & {- 3} & 1
        \end{array} \right\rbrack\left\lbrack \begin{array}{l}
        \mathbf{p}_{0} \\
        \mathbf{p}_{1} \\
        \mathbf{p}_{2} \\
        \mathbf{p}_{3}
        \end{array} \right\rbrack} \\
         & = & {\left\lbrack {(1 - s)}^{3} 3s{(1 - s)}^{2} 3s^{2}(1 - s) s^{3} \right\rbrack\left\lbrack \begin{array}{l}
        \mathbf{p}_{0} \\
        \mathbf{p}_{1} \\
