        \mathbf{p}_{3}
        \end{array} \right\rbrack}
        \end{matrix}$$

statement.paragraph:
A $\text{B-spline}$ is built out of $\text{B-spline}$ segments, described in Exercise 2. Let $\textbf{p}_{0},\ldots,\textbf{p}_{4}$ be control points. For $0 \leq t \leq 1$, let $\textbf{x}(t)$ and $\textbf{y}(t)$ be determined by the geometry matrices $\text{[}\begin{matrix}
        \mathbf{p}_{0} & \mathbf{p}_{1} & \mathbf{p}_{2} & \mathbf{p}_{3}
        \end{matrix}\text{]}$ and $\text{[}\begin{matrix}
        \mathbf{p}_{1} & \mathbf{p}_{2} & \mathbf{p}_{3} & \mathbf{p}_{4}
        \end{matrix}\text{]}$, respectively. Notice how the two segments share three control points. The two segments do not overlap, however—they join at a common endpoint, close to $\textbf{p}_{2}$.﻿

statement.math:
$$\begin{matrix}
        {\mathbf{x}(t)\, = (1 - t)^{4}\mathbf{p}_{0} + 4t(1 - t)^{3}\mathbf{p}_{1} + 6t^{2}\left( {1 - t} \right)^{2}\mathbf{p}_{2} + 4t^{3}\left( {1 - t} \right)\mathbf{p}_{3} + t^{4}\mathbf{p}_{4}} & {\text{for~~0} \leq t \leq 1}
        \end{matrix}$$
